import { useCallback, useEffect, useMemo, useState } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import { useHasPermission } from '../hooks/usePermission';
import type { PaginatedPayload, RoleRow, StaffUserRow } from '../types/roles.types';
import { cn } from '@/lib/utils';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Check, ChevronsUpDown, Plus } from 'lucide-react';

type ComboOption = { value: string; label: string; subLabel?: string };

function SearchableCombobox({
    value,
    onChange,
    options,
    placeholder,
    disabled,
}: {
    value: string;
    onChange: (next: string) => void;
    options: ComboOption[];
    placeholder: string;
    disabled?: boolean;
}) {
    const selected = options.find((o) => o.value === value);
    return (
        <Popover>
            <PopoverTrigger asChild disabled={disabled}>
                <Button
                    variant="outline"
                    role="combobox"
                    className={cn('h-10 w-full justify-between rounded-xl', !selected && 'text-muted-foreground')}
                >
                    <span className="truncate">{selected ? selected.label : placeholder}</span>
                    <ChevronsUpDown className="h-4 w-4 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[--radix-popover-trigger-width] p-0" align="start">
                <Command>
                    <CommandInput placeholder="بحث…" />
                    <CommandList>
                        <CommandEmpty>لا توجد نتائج</CommandEmpty>
                        <CommandGroup>
                            {options.map((opt) => {
                                const isSelected = opt.value === value;
                                return (
                                    <CommandItem
                                        key={opt.value}
                                        value={`${opt.label} ${opt.subLabel ?? ''}`.trim()}
                                        onSelect={() => onChange(opt.value)}
                                    >
                                        <div
                                            className={cn(
                                                'me-2 flex h-4 w-4 items-center justify-center rounded-sm border border-primary',
                                                isSelected
                                                    ? 'bg-primary text-primary-foreground'
                                                    : 'opacity-50 [&_svg]:invisible',
                                            )}
                                        >
                                            <Check className="h-4 w-4" />
                                        </div>
                                        <div className="min-w-0">
                                            <div className="truncate">{opt.label}</div>
                                            {opt.subLabel ? (
                                                <div className="truncate text-xs text-muted-foreground" dir="ltr">
                                                    {opt.subLabel}
                                                </div>
                                            ) : null}
                                        </div>
                                    </CommandItem>
                                );
                            })}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

function RemoteUserSearchPicker({
    displayText,
    onPick,
    disabled,
}: {
    displayText: string;
    onPick: (id: string, display: string) => void;
    disabled?: boolean;
}) {
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState('');
    const [debounced, setDebounced] = useState('');
    const [rows, setRows] = useState<StaffUserRow[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const t = setTimeout(() => setDebounced(search.trim()), 300);
        return () => clearTimeout(t);
    }, [search]);

    const fetchRows = useCallback(async (q: string) => {
        setLoading(true);
        try {
            const res = await apiGet<{ data: PaginatedPayload<StaffUserRow> }>({
                endpoint: endpoints.accessControl.userRoleAssignmentList,
                queryParams: { page: 1, pageSize: 50, search: q },
            });
            setRows(res.data?.data?.data ?? []);
        } catch {
            setRows([]);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        if (!open) return;
        fetchRows(debounced);
    }, [open, debounced, fetchRows]);

    useEffect(() => {
        if (open) {
            setSearch('');
            setDebounced('');
        }
    }, [open]);

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild disabled={disabled}>
                <Button
                    variant="outline"
                    role="combobox"
                    className={cn(
                        'h-auto min-h-10 w-full justify-between rounded-xl py-2',
                        !displayText && 'text-muted-foreground',
                    )}
                >
                    <span className="truncate text-start leading-snug">
                        {displayText || 'ابحث واختر بالبريد أو الاسم…'}
                    </span>
                    <ChevronsUpDown className="h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[min(100vw-2rem,520px)] p-3" align="start">
                <Input
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="بحث بالاسم أو البريد أو الجوال…"
                    className="mb-2"
                    dir="rtl"
                />
                <div className="max-h-64 space-y-1 overflow-y-auto">
                    {loading ? (
                        <p className="p-2 text-sm text-muted-foreground">جاري التحميل…</p>
                    ) : rows.length === 0 ? (
                        <p className="p-2 text-sm text-muted-foreground">لا توجد نتائج</p>
                    ) : (
                        rows.map((u) => (
                            <button
                                key={u.id}
                                type="button"
                                className="w-full rounded-lg border border-transparent px-2 py-2 text-start text-sm transition-colors hover:border-primery-blue-200 hover:bg-primery-blue-500/[0.04]"
                                onClick={() => {
                                    const display = u.email ? `${u.name ?? ''} — ${u.email}`.replace(/^\s*—\s*/, '') : (u.name ?? '');
                                    onPick(String(u.id), display);
                                    setOpen(false);
                                }}
                            >
                                <div className="font-medium text-white-blue-900">{u.name}</div>
                                <div className="text-xs text-muted-foreground" dir="ltr">
                                    {u.email}
                                </div>
                            </button>
                        ))
                    )}
                </div>
            </PopoverContent>
        </Popover>
    );
}

const UserRoleAssignmentPage = () => {
    const canList = useHasPermission('list_user');
    const canListRole = useHasPermission('list_role');
    const canEdit = useHasPermission('edit_user');

    const [users, setUsers] = useState<StaffUserRow[]>([]);
    const [roles, setRoles] = useState<RoleRow[]>([]);
    const [page, setPage] = useState(1);
    const [lastPage, setLastPage] = useState(1);
    const [loadingUsers, setLoadingUsers] = useState(true);
    const [loadingRoles, setLoadingRoles] = useState(true);
    const [tableSearch, setTableSearch] = useState('');
    const [debouncedTableSearch, setDebouncedTableSearch] = useState('');
    const [draftRoleId, setDraftRoleId] = useState<Record<number, string>>({});
    const [savingId, setSavingId] = useState<number | null>(null);

    const [assignOpen, setAssignOpen] = useState(false);
    const [assignUserId, setAssignUserId] = useState('');
    const [assignUserDisplay, setAssignUserDisplay] = useState('');
    const [assignRoleId, setAssignRoleId] = useState('');
    const [assignSaving, setAssignSaving] = useState(false);

    useEffect(() => {
        const t = setTimeout(() => setDebouncedTableSearch(tableSearch.trim()), 350);
        return () => clearTimeout(t);
    }, [tableSearch]);

    useEffect(() => {
        setPage(1);
    }, [debouncedTableSearch]);

    const loadRoles = useCallback(async () => {
        if (!canListRole) {
            setRoles([]);
            setLoadingRoles(false);
            return;
        }
        setLoadingRoles(true);
        try {
            const res = await apiGet<{ data: RoleRow[] }>({
                endpoint: endpoints.accessControl.roleSelectList,
            });
            const raw = res.data?.data;
            const rows = Array.isArray(raw) ? raw : [];
            setRoles(rows.filter((r) => r.slug !== 'user'));
        } catch {
            setRoles([]);
            toast.error('تعذر تحميل قائمة الأدوار');
        } finally {
            setLoadingRoles(false);
        }
    }, [canListRole]);

    const loadUsers = useCallback(async () => {
        setLoadingUsers(true);
        try {
            const res = await apiGet<{ data: PaginatedPayload<StaffUserRow> }>({
                endpoint: endpoints.accessControl.userRoleAssignmentList,
                queryParams: { page, pageSize: 15, search: debouncedTableSearch },
            });
            const payload = res.data?.data;
            const rows = payload?.data ?? [];
            setUsers(rows);
            setLastPage(payload?.pagination?.last_page ?? 1);
            setDraftRoleId(() => {
                const next: Record<number, string> = {};
                for (const u of rows) {
                    const first = u.roles?.[0]?.id;
                    next[u.id] = first != null ? String(first) : '';
                }
                return next;
            });
        } catch {
            setUsers([]);
            toast.error('تعذر تحميل المستخدمين');
        } finally {
            setLoadingUsers(false);
        }
    }, [page, debouncedTableSearch]);

    useEffect(() => {
        if (canList) {
            loadRoles();
        } else {
            setLoadingRoles(false);
        }
    }, [canList, loadRoles]);

    useEffect(() => {
        if (canList) {
            loadUsers();
        } else {
            setLoadingUsers(false);
        }
    }, [canList, loadUsers]);

    const handleInlineSave = async (userId: number) => {
        const rid = draftRoleId[userId];
        if (!rid) {
            toast.error('اختر دوراً');
            return;
        }
        setSavingId(userId);
        try {
            await apiPost({
                endpoint: `${endpoints.accessControl.userAssignRole}${userId}`,
                body: { role_id: Number(rid) },
            });
            toast.success('تم تعيين الدور');
            await loadUsers();
        } catch (err: unknown) {
            const msg =
                err && typeof err === 'object' && 'response' in err
                    ? (err as { response?: { data?: { msg?: string } } }).response?.data?.msg
                    : null;
            toast.error(msg || 'فشل الحفظ');
        } finally {
            setSavingId(null);
        }
    };

    const isBusy = loadingUsers || loadingRoles;
    const colCount = canEdit ? 5 : 4;

    const roleSelectOptions = useMemo(
        () =>
            roles.map((r) => (
                <option key={r.id} value={r.id}>
                    {r.name}
                </option>
            )),
        [roles],
    );

    const comboRoleOptions = useMemo<ComboOption[]>(
        () => roles.map((r) => ({ value: String(r.id), label: r.name })),
        [roles],
    );

    if (!canList) {
        return <p className="mt-8 px-4 text-sm text-white-blue-700">ليس لديك صلاحية عرض المستخدمين.</p>;
    }

    return (
        <div className="mx-auto mt-6 w-full max-w-5xl px-4 pb-14">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
                <div>
                    <UnderlineHeading text="تعيين الأدوار للمستخدمين" />
                    <p className="mt-3 max-w-3xl text-sm leading-relaxed text-white-blue-700">
                        يظهر هنا المستخدمون الإداريون، وأيضاً حسابات الموظفين التي أنشأها النظام عند إضافة موظف (نفس بريد
                        الموظف في جدول <span className="font-mono text-xs">users</span> و<span className="font-mono text-xs">employees</span>).
                        إن كان موظفاً بدون حساب دخول، لن يظهر حتى يُنشأ له مستخدم.
                    </p>
                </div>
                {canEdit && (
                    <PrimaryButton
                        type="button"
                        className="inline-flex items-center gap-2 !py-2.5"
                        onClick={() => {
                            setAssignOpen(true);
                            setAssignUserId('');
                            setAssignUserDisplay('');
                            setAssignRoleId('');
                        }}
                    >
                        <Plus className="h-4 w-4" />
                        تعيين دور
                    </PrimaryButton>
                )}
            </div>

            <div className="mt-4 max-w-md">
                <Input
                    value={tableSearch}
                    onChange={(e) => setTableSearch(e.target.value)}
                    placeholder="بحث في الجدول بالاسم أو البريد…"
                    dir="rtl"
                />
            </div>

            <div
                className={cn(
                    'mt-6 overflow-hidden rounded-2xl border border-[#E4E2EC] bg-white shadow-[0_12px_40px_-12px_rgba(12,12,13,0.12)]',
                    isBusy && 'pointer-events-none opacity-70',
                )}
            >
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[640px] text-start text-sm">
                        <thead>
                            <tr className="border-b border-[#E4E2EC] bg-gradient-to-l from-primery-blue-500/8 to-transparent">
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">المستخدم</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">البريد</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">الدور الحالي</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">تعيين</th>
                                {canEdit && <th className="w-28 px-4 py-3.5 font-semibold text-primery-blue-600"> </th>}
                            </tr>
                        </thead>
                        <tbody>
                            {users.length === 0 && !loadingUsers ? (
                                <tr>
                                    <td colSpan={colCount} className="px-4 py-10 text-center text-white-blue-700">
                                        لا يوجد مستخدمون مطابقون.
                                    </td>
                                </tr>
                            ) : (
                                users.map((u) => {
                                    const currentLabel = u.roles?.map((r) => r.name).join('، ') || '—';
                                    return (
                                        <tr
                                            key={u.id}
                                            className="border-b border-[#F0EEF5] last:border-0 hover:bg-primery-blue-500/[0.03]"
                                        >
                                            <td className="px-4 py-3.5 font-medium text-white-blue-900">{u.name}</td>
                                            <td className="px-4 py-3.5 text-white-blue-700" dir="ltr">
                                                {u.email}
                                            </td>
                                            <td className="px-4 py-3.5">
                                                <span className="inline-flex rounded-full border border-primery-blue-100 bg-primery-blue-500/5 px-3 py-1 text-xs font-medium text-primery-blue-700">
                                                    {currentLabel}
                                                </span>
                                            </td>
                                            <td className="min-w-[200px] px-4 py-3.5">
                                                <select
                                                    className="w-full rounded-lg border border-[#D8D6DE] bg-white px-3 py-2 text-sm text-white-blue-900 shadow-sm focus:border-primery-blue-400 focus:outline-none focus:ring-1 focus:ring-primery-blue-400"
                                                    value={draftRoleId[u.id] ?? ''}
                                                    disabled={!canEdit}
                                                    onChange={(e) =>
                                                        setDraftRoleId((prev) => ({
                                                            ...prev,
                                                            [u.id]: e.target.value,
                                                        }))
                                                    }
                                                >
                                                    <option value="">— اختر دوراً —</option>
                                                    {roleSelectOptions}
                                                </select>
                                            </td>
                                            {canEdit && (
                                                <td className="px-4 py-3.5">
                                                    <PrimaryButton
                                                        type="button"
                                                        className="!px-3 !py-1.5 text-xs"
                                                        disabled={savingId === u.id || !draftRoleId[u.id]}
                                                        onClick={() => handleInlineSave(u.id)}
                                                    >
                                                        {savingId === u.id ? '…' : 'حفظ'}
                                                    </PrimaryButton>
                                                </td>
                                            )}
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>

                {lastPage > 1 && (
                    <div className="flex items-center justify-between gap-4 border-t border-[#E4E2EC] bg-[#FAFAFC] px-4 py-3">
                        <span className="text-xs text-white-blue-700">
                            صفحة {page} من {lastPage}
                        </span>
                        <div className="flex gap-2">
                            <button
                                type="button"
                                className="rounded-lg border border-[#D8D6DE] bg-white px-3 py-1.5 text-xs font-medium text-primery-blue-600 disabled:opacity-40"
                                disabled={page <= 1}
                                onClick={() => setPage((p) => Math.max(1, p - 1))}
                            >
                                السابق
                            </button>
                            <button
                                type="button"
                                className="rounded-lg border border-[#D8D6DE] bg-white px-3 py-1.5 text-xs font-medium text-primery-blue-600 disabled:opacity-40"
                                disabled={page >= lastPage}
                                onClick={() => setPage((p) => p + 1)}
                            >
                                التالي
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <Dialog open={assignOpen} onOpenChange={setAssignOpen}>
                <DialogContent className="max-w-xl rounded-2xl">
                    <DialogHeader>
                        <DialogTitle className="text-primery-blue-700">تعيين دور لمستخدم</DialogTitle>
                    </DialogHeader>

                    <div className="space-y-4">
                        <div>
                            <label className="mb-2 block text-sm font-medium text-primery-blue-600">
                                المستخدم (بحث بالبريد أو الاسم)
                            </label>
                            <RemoteUserSearchPicker
                                displayText={assignUserDisplay}
                                onPick={(id, display) => {
                                    setAssignUserId(id);
                                    setAssignUserDisplay(display);
                                }}
                                disabled={!canEdit}
                            />
                        </div>
                        <div>
                            <label className="mb-2 block text-sm font-medium text-primery-blue-600">الدور</label>
                            {!canListRole ? (
                                <p className="text-sm text-muted-foreground">ليس لديك صلاحية عرض قائمة الأدوار.</p>
                            ) : (
                                <SearchableCombobox
                                    value={assignRoleId}
                                    onChange={setAssignRoleId}
                                    options={comboRoleOptions}
                                    placeholder={loadingRoles ? 'جاري التحميل…' : 'اختر دوراً'}
                                    disabled={loadingRoles || !canEdit}
                                />
                            )}
                        </div>
                    </div>

                    <DialogFooter className="mt-2 flex flex-row items-center justify-end gap-2 sm:space-x-0">
                        <Button variant="outline" onClick={() => setAssignOpen(false)}>
                            إلغاء
                        </Button>
                        <PrimaryButton
                            type="button"
                            disabled={
                                !assignUserId ||
                                !assignRoleId ||
                                assignSaving ||
                                !canEdit ||
                                !canListRole ||
                                loadingRoles
                            }
                            onClick={async () => {
                                setAssignSaving(true);
                                try {
                                    await apiPost({
                                        endpoint: `${endpoints.accessControl.userAssignRole}${assignUserId}`,
                                        body: { role_id: Number(assignRoleId) },
                                    });
                                    toast.success('تم تعيين الدور');
                                    setAssignOpen(false);
                                    await loadUsers();
                                } catch (err: unknown) {
                                    const msg =
                                        err && typeof err === 'object' && 'response' in err
                                            ? (err as { response?: { data?: { msg?: string } } }).response?.data?.msg
                                            : null;
                                    toast.error(msg || 'فشل الحفظ');
                                } finally {
                                    setAssignSaving(false);
                                }
                            }}
                        >
                            {assignSaving ? 'جاري الحفظ…' : 'حفظ'}
                        </PrimaryButton>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default UserRoleAssignmentPage;
